For a given ORB-type GRAND algorithm, the BLER averaged over the random code ensemble is
    \begin{align}
        P_{\text{err}} = 1 - P_{\text{succ}} = 1 - \sum_{t=1}^{T}p_t\left(\prod_{i=1}^{t-1}\frac{2^N-2^K+1-i}{2^N-i}\right),
    \end{align}
    where $p_t = \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) \mid \underline{Y})\right]$, $T$ denotes the maximum number of tests allowed by the decoder.

For ORB-type decoding applied to the random code ensemble, impose a maximum number of tests $T$ and consider the EP set available to the decoder. The decoding success probability $P_{\mathrm{succ}}$ is maximized by selecting the tested EPs so that their AGPs dominate those of the untested EPs and ordering the tested EPs in non-increasing AGP order, i.e.,
 \begin{equation}
     p_1\geq p_2\geq \cdots\geq p_T, \text{ and }\ p_i\geq p_j,\ \forall \ i\leq T<j.
 \end{equation}
This ordering also minimizes the average number of tests.

The target-miss probability is given by
    \begin{align}
        P_{\text{I}} = \Pr(\theta(\underline{Y})\oplus \pi(\underline{e}(t))\neq \underline{W}(1),\forall\ t \leq T) = 1 - \sum_{t=1}^{T} p_t, 
    \end{align}
    where $p_t = \mathbf{E}_{\underline{Y}}\left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \pi(\underline{e}(t)) \mid \underline{Y})\right]$.

The target-preemption probability is given by:
    \begin{align}
        P_{\mathrm{II}} = \sum_{t=1}^{T} p_{t} \left(1 - \prod_{t' = 1}^{t-1} \frac{2^N-2^K+1-t'}{2^N-t'}\right). 
    \end{align}

For a given ORB-type GRAND algorithm, over the random code ensemble, the probability that the codeword tester declares the decoded codeword after $t$ tests is given by:
     \begin{eqnarray}
         P_{\text{stop}}(t) &=& p_t (1 - f(t)) + \left(1-\sum_{i=1}^{t}p_i\right)(f(t+1)-f(t)), \quad\quad t = 1, \ldots, T - 1;\\
         P_{\text{stop}}(T) &=& \left(1-\sum_{i=1}^{T-1}p_i\right)(1-f(T)).
     \end{eqnarray}

Consider an output-symmetric channel satisfying (1) and a permutation rule $\pi_{\underline y}$ that depends on $\underline y$ only through the reliability values $|\ell_1|,\ldots,|\ell_N|$. Then for any codebook $\mathcal C$, we have
    \begin{equation}
        \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \pi(\underline{e}) \mid \underline{Y})\right] = \int_{\mathbb{R}^N}\prod_{i=1}^{N}p_{Y}(y_i) \left(\prod_{i:\pi_{\underline{y}}(\underline{e})_i = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:\pi_{\underline{y}}(\underline{e})_i = 0} \frac{\exp(|\ell_i|)} {1+\exp(|\ell_i|)}\right)\mathrm{d}\underline{y},
    \end{equation}



    In particular, for the rank-based permutation, we have:
    \begin{align}
        p_t = N!\int_{\underline{y}:|\ell_{1}|<|\ell_{2}|<\cdots<|\ell_{N}|}\prod_{i=1}^{N}p_{Y}(y_i)\left(\prod_{i:e_i(t) = 1} \frac{1}{1+\exp(|\ell_i|)} \prod_{i:e_i(t) = 0} \frac{\exp(|\ell_i|)}{1+\exp(|\ell_i|)}\right)\mathrm{d}\underline{y}.
    \end{align}

For a given ORB-type GRAND algorithm, the quantities $\{p_t\}_{t=1}^T$ describe the probability distribution of the position of the target EP in the ordered sequence $\{\pi(\underline{e}(t))\}$, i.e.,
\begin{equation}
p_t
=
\Pr(\theta(\underline{Y})\oplus\pi(\underline{e}(t))=\underline{W}(1)).
\end{equation}

For the random code ensemble, the pre-target codeword-hit probability is given by:
    \begin{equation}
        f(\mathbfcal{C},\mathcal{E},t) = 1 - \prod_{t'=1}^{t-1}\frac{2^N-2^K+1-t'}{2^N-t'},
    \end{equation}
    for $t = 2, \ldots, T$, and $f(\mathbfcal{C},\mathcal{E},1) = 0$.

For a given ORB-type GRAND algorithm, conditioned on the event that the codeword tester stops after the $t$-th test, the probability that the declared codeword equals the transmitted codeword is
    \begin{align}
        P_{\text{succ}\mid\text{stop}}(t) &= \frac{p_t}{p_t + (1 - \sum_{i=1}^{t}p_i)\left( \frac{2^K-1}{2^N-t}\right)}, \quad\quad t = 1, \ldots, T - 1;\\
        P_{\text{succ}\mid\text{stop}}(T) &= \frac{p_T}{1 - \sum_{i=1}^{T-1}p_i}.
    \end{align}

For a given linear block code $\mathcal{C}$ and a given ORB-type GRAND algorithm, the BLER is given by
    \begin{equation}
        P_{\text{err}} = 1 - P_{\text{succ}} =  1 - \sum_{t=1}^{T} p_t \Pr\!\left( \pi(\underline{e}(t') \oplus \underline{e}(t)) \notin \mathcal{C}, \forall\, t' < t \,\middle|\, \theta(\underline{Y})\oplus \pi(\underline{e}(t))=\underline{W}(1) \right)
    \end{equation}
    where $p_t = \mathbf{E}_{\underline{Y}} \left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus \pi(\underline{e}(t))\mid\underline{Y})\right]$.

    If the channel is output-symmetric and the permutation $\pi$ is the rank-based permutation, the expression simplifies to
    \begin{equation}
        P_{\text{err}} = 1 - \sum_{t=1}^{T}p_t\Pr(\pi(\underline{e}(t') \oplus \underline{e}(t)) \notin \mathcal{C},\forall\, t'< t).
    \end{equation}

For any linear block code and any output-symmetric channel, consider ORB-type GRAND decoding with $\pi$ the rank-based permutation. Fix a $T$-element candidate EP set and consider all its orderings. Among the orderings that maximize the decoding success probability, at least one has an associated sequence $\{p_t\}_{t=1}^{T}$ that is non-increasing, i.e.,
\begin{equation}
    p_1 \ge p_2 \ge \cdots \ge p_{T},
\end{equation}
where $p_t=\mathbf{E}_{\underline{Y}}\!\left[P_{\underline{W}|\underline{Y}}(\theta(\underline{Y})\oplus\pi(\underline{e}(t))\mid\underline{Y})\right].$

For any linear block code $\mathcal{C}$, the pre-target codeword-hit probability admits the representation
\begin{equation}
f(\mathcal{C},\mathcal{E},t)
= \sum_{j=1}^{t-1} (-1)^{j-1}
\sum_{1\le i_1<\cdots<i_j<t}
\frac{1}{N!}\,
Z(\mathbf{g})\,
\mathcal{H}(\mathbf{g}),
\end{equation}
where $\mathbf{g}=\mathcal{F}(\underline{e}(i_1,t),\ldots,\underline{e}(i_j,t))$, and $\mathcal{H}(\mathbf{g})$ is the coordinate-permutation factor characterized in Proposition~8.

For any $1\le i_1<i_2<\cdots<i_j<t$, the joint probability 
$\Pr\!\left(\bigcap_{k=1}^{j}A_{i_k t}\right)$ can be expressed as
\begin{equation}
\sum_{\substack{
[\underline{u}(1),\ldots,\underline{u}(j)] \in \mathcal{C}^{j}:\\
\mathcal{F}(\underline{u}(1),\ldots,\underline{u}(j)) = \mathbf{g}
}}
\Pr\!\left(
\bigcap_{k=1}^{j}\{\pi(\underline{e}(i_k,t))=\underline{u}(k)\}
\right),

\end{equation}
where $\mathbf{g} = \mathcal{F}\big(\underline{e}(i_1,t),\ldots,\underline{e}(i_j,t)\big)$.

For any two ordered binary vector tuples 
$[\underline{x}(1),\ldots,\underline{x}(j)]$ and 
$[\underline{u}(1),\ldots,\underline{u}(j)]$, suppose that
\begin{equation}
\mathcal{F}(\underline{x}(1),\ldots,\underline{x}(j))
=
\mathcal{F}(\underline{u}(1),\ldots,\underline{u}(j))
=
\mathbf{g}.
\end{equation}
For each coordinate $k$, define the state of $[\underline{x}(1),\ldots,\underline{x}(j)]$ by
\begin{equation}
\underline{S}_x(k)=[x_k(1),\ldots,x_k(j)]\in\{0,1\}^j,
\end{equation}
and define $\underline{S}_u(k)$ similarly. Let
\begin{equation}
J(\underline{s})=\bigl|\{k:\underline{S}_x(k)=\underline{s}\}\bigr|,
\qquad \underline{s}\in\{0,1\}^j.
\end{equation}
Then the number of coordinate permutations $\sigma$ satisfying
$\sigma(\underline{x}(i))=\underline{u}(i)$ for all $i=1,\ldots,j$ is
\begin{equation}
\mathcal{H}(\mathbf{g})
=
\prod_{\underline{s}\in\{0,1\}^j} J(\underline{s})!.
\end{equation}

Let $\mathbf{g}^{(j)}=\bigl(g(\underline{b})\bigr)_{\underline{b}\in\{0,1\}^j}$ and $\mathbf{J}^{(j)}=\bigl(J(\underline{s})\bigr)_{\underline{s}\in\{0,1\}^j}$, where both vectors are ordered according to the lexicographic order on $\{0,1\}^j$. Then
\begin{equation}
\mathbf{g}^{(j)}=\mathbf{B}_j\,\mathbf{J}^{(j)},
\end{equation}
where the matrix-vector product is taken over the integers, and $\mathbf{B}_j$ is the $2^j\times 2^j$ matrix indexed by $\{0,1\}^j\times\{0,1\}^j$ with entries
\begin{equation}
\bigl[\mathbf{B}_j\bigr]_{\underline{b},\underline{s}}
=
\begin{cases}
1, & \underline{b}=\underline{0},\\
\underline{b}\cdot \underline{s}, & \underline{b}\neq \underline{0},
\end{cases}
\qquad
\underline{b},\underline{s}\in\{0,1\}^j,
\end{equation}
and $\underline{b}\cdot \underline{s}=\bigoplus_{i=1}^j b_i s_i$.
Moreover, $\mathbf{B}_j$ admits the recursion
\begin{equation}
\mathbf{B}_{j+1}
=
\begin{bmatrix}
\mathbf{B}_j & \mathbf{B}_j\\
\mathbf{E}^{2^j\times 2^j}_{1,1:2^j}\oplus \mathbf{B}_j &
\mathbf{E}^{2^j\times 2^j}_{1,1:2^j}\oplus \mathbf{1}^{2^j\times 2^j}\oplus \mathbf{B}_j
\end{bmatrix},
\qquad
\mathbf{B}_1=
\begin{bmatrix}
1 & 1\\
0 & 1
\end{bmatrix}.
\end{equation}
Furthermore, $\mathbf{B}_j$ is invertible over $\mathbb{R}$, and hence $\mathbf{J}^{(j)}$ can be uniquely recovered from $\mathbf{g}^{(j)}$ via $\mathbf{J}^{(j)}=\mathbf{B}_j^{-1}\mathbf{g}^{(j)}$.
